    String descricao,
    // Indicação que será considerada pelas regras da aplicação.
    boolean ativo
) {}

package br.edu.soa.restaurante.dominio;

// Tipo decimal do JDK utilizado para representar o preço.
import java.math.BigDecimal;

// Dados de um produto oferecido no cardápio.
public record Produto(
    // Identificação técnica do produto.
    long id,
    // Identificação da categoria à qual o produto pertence.
    long categoriaId,
    String nome,
    String descricao,
    // Caminho ou URL que a interface usará para apresentar a imagem.
    String imagem,
    // Valor decimal usado nas novas inclusões em pedidos.
    BigDecimal preco,
    // Por exemplo: Copo de 500 ml ou Serve duas pessoas.
    String porcao,
    // Indicação considerada pela aplicação ao incluir o produto.
    boolean disponivel
) {}

package br.edu.soa.restaurante.dominio;

import java.math.BigDecimal;

// Dados de uma inclusão de produto em um pedido.
public record ItemPedido(
    long id,
    long produtoId,
    // Nome recebido no momento da inclusão, para preservar o histórico.
    String nomeProduto,
    int quantidade,
    // Preço recebido na inclusão, independente de mudanças no catálogo.
    BigDecimal precoUnitario
) {
    // Construtor compacto: valida os argumentos antes de guardar os campos.
    public ItemPedido {
        // Aceita quantidades de 1 até 10000, inclusive.
        if (quantidade <= 0 || quantidade > 10000)
            throw new IllegalArgumentException("Quantidade entre 1 e 10000.");
    }

    // Calcula o valor desse item: preço unitário multiplicado pela quantidade.
    public BigDecimal subtotal() {
        // Converte a quantidade inteira para BigDecimal antes de multiplicar.
        return precoUnitario.multiply(BigDecimal.valueOf(quantidade));
    }
}

// Finalidade: Representar a conta de uma mesa e calcular seu total pelos itens.
package br.edu.soa.restaurante.dominio;
import java.math.BigDecimal;
import java.time.Instant;
import java.util.List;
public record Pedido(long id, long mesaId, Instant dataHora, SituacaoPedido situacao, List<ItemPedido> itens) {
 // Copia a lista recebida para impedir mudanças externas na coleção do pedido.
 public Pedido { itens = List.copyOf(itens); }
 // Soma os subtotais dos itens com BigDecimal, partindo de zero.
 public BigDecimal total() { return itens.stream().map(ItemPedido::subtotal).reduce(new BigDecimal("0.00"), BigDecimal::add); }
}

// Finalidade: Classificar recusas e falhas da aplicação sem depender do protocolo.
package br.edu.soa.restaurante.aplicacao;

/** Erro sem dependência de SOAP, HTTP ou detalhes de SQL. */
public final class Falha extends RuntimeException {
    public enum Tipo { VALIDACAO, NAO_ENCONTRADO, CONFLITO, INTERNO }
    private final String codigo;
    private final Tipo tipo;

    public Falha(String codigo, Tipo tipo, String mensagem) {
        super(mensagem);
        this.codigo = codigo;
        this.tipo = tipo;
    }
    public String codigo() { return codigo; }
    public Tipo tipo() { return tipo; }
    public static Falha invalido(String mensagem) { return new Falha("ENTRADA_INVALIDA", Tipo.VALIDACAO, mensagem); }
    public static Falha conflito(String codigo, String mensagem) { return new Falha(codigo, Tipo.CONFLITO, mensagem); }
}

// Finalidade: Definir as operações de persistência necessárias aos casos de uso.
package br.edu.soa.restaurante.aplicacao;

import br.edu.soa.restaurante.dominio.*;
import java.util.List;
import java.util.function.Function;

/** Unidade de trabalho: toda função usa uma conexão e termina com commit ou rollback. */
public interface Repositorio {
    // Executa uma unidade de trabalho; a implementação administra confirmação e reversão.
    <T> T transacao(Function<Sessao, T> trabalho);

    interface Sessao {
        Mesa mesa(long id, boolean bloquear);
        List<Mesa> mesas();
        // Define a gravação do número da mesa; as regras de ocupação pertencem à aplicação.
        Mesa salvarMesa(long id, int numero);
        void ocuparMesa(long id, SituacaoMesa situacao);
        // Exclui a mesa pelo ID; a aplicação confere sua situação antes de chamar a persistência.
        void excluirMesa(long id);
        Categoria categoria(long id);
        List<Categoria> categorias();
        // Insere ou atualiza os dados da categoria pelo contrato de persistência.
        Categoria salvarCategoria(Categoria categoria);
        // Executa a exclusão; chaves estrangeiras protegem os vínculos existentes.
        void excluirCategoria(long id);
        Produto produto(long id, boolean bloquear);
        List<Produto> produtos();
        // Grava os dados recebidos do produto; a validação de negócio ocorre em Restaurante.
        Produto salvarProduto(Produto produto);
        void excluirProduto(long id);
        Pedido pedido(long id, boolean bloquear);
        List<Pedido> pedidos();
        Pedido inserirPedido(long mesaId);
        // Guarda nome e preço do produto como dados históricos da inclusão.
        void inserirItem(long pedidoId, Produto produto, int quantidade);
        void quantidadeItem(long pedidoId, long itemId, int quantidade);
        void removerItem(long pedidoId, long itemId);
        void encerrarPedido(long id, SituacaoPedido situacao);
    }
}

