    // Confere a situação da mesa antes de solicitar a exclusão.
    public void excluirMesa(long id) {
        repositorio.transacao(s -> {
            if (s.mesa(id, true).situacao() == SituacaoMesa.OCUPADA)
                throw Falha.conflito("MESA_OCUPADA", "Mesa possui pedido aberto.");
            s.excluirMesa(id); return null;
        });
    }
    // Consulta o catálogo de categorias.
    public List<Categoria> listarCategorias() { return repositorio.transacao(Repositorio.Sessao::categorias); }
    public Categoria consultarCategoria(long id) { return repositorio.transacao(s -> s.categoria(id)); }
    // Valida os textos e coordena o cadastro da categoria.
    public Categoria salvarCategoria(long id, String nome, String descricao, boolean ativo) {
        if (id < 0) throw Falha.invalido("ID não negativo.");
        Categoria c = new Categoria(id, texto(nome, "Nome", 120), opcional(descricao, 2000), ativo);
        return repositorio.transacao(s -> { if (id > 0) s.categoria(id); return s.salvarCategoria(c); });
    }
    // Solicita a exclusão; vínculos existentes serão protegidos pela persistência.
    public void excluirCategoria(long id) {
        repositorio.transacao(s -> { s.categoria(id); s.excluirCategoria(id); return null; });
    }
    public List<Produto> listarProdutos() { return repositorio.transacao(Repositorio.Sessao::produtos); }
    public List<Produto> listarProdutosPorCategoria(long categoriaId) {
        return repositorio.transacao(s -> { s.categoria(categoriaId); return s.produtos().stream().filter(p -> p.categoriaId() == categoriaId).toList(); });
    }
    public Produto consultarProduto(long id) { return repositorio.transacao(s -> s.produto(id, false)); }
    // Valida a categoria e os dados, inclusive o valor monetário, antes de gravar.
    public Produto salvarProduto(long id, long categoriaId, String nome, String descricao, String imagem,
                                  BigDecimal preco, String porcao, boolean disponivel) {
        if (id < 0) throw Falha.invalido("ID não negativo.");
        if (preco == null || preco.signum() < 0 || preco.compareTo(new BigDecimal("9999999.99")) > 0)
            throw Falha.invalido("Preço entre 0 e 9999999,99.");
        BigDecimal dinheiro;
        try { dinheiro = preco.setScale(2, RoundingMode.UNNECESSARY); }
        catch (ArithmeticException e) { throw Falha.invalido("Preço deve ter no máximo duas casas decimais."); }
        Produto p = new Produto(id, categoriaId, texto(nome, "Nome", 160), opcional(descricao, 2000),
                imagem(imagem), dinheiro, texto(porcao, "Porção", 160), disponivel);
        return repositorio.transacao(s -> {
            if (id > 0) s.produto(id, true);
            if (!s.categoria(categoriaId).ativo()) throw Falha.invalido("Categoria deve estar ativa.");
            return s.salvarProduto(p);
        });
    }
    public void excluirProduto(long id) {
        repositorio.transacao(s -> { s.produto(id, true); s.excluirProduto(id); return null; });
    }
    /** Projeção pública: não retorna pedidos, usuários ou mesas ocupadas. */
    // Monta a projeção pública de categorias e produtos disponíveis.
    public Cardapio cardapio() {
        return repositorio.transacao(s -> {
            List<Categoria> cats = s.categorias().stream().filter(Categoria::ativo).toList();
            return new Cardapio(cats, s.produtos().stream().filter(p -> cats.stream().anyMatch(c -> c.id() == p.categoriaId())).toList());
        });
    }
    public record Cardapio(List<Categoria> categorias, List<Produto> produtos) {}

    private static String texto(String s, String nome, int limite) {
        if (s == null || s.isBlank() || s.length() > limite) throw Falha.invalido(nome + " obrigatório, limite de " + limite + " caracteres.");
        return s.trim();
    }
    private static String opcional(String s, int limite) {
        if (s == null) return "";
        if (s.length() > limite) throw Falha.invalido("Texto excede " + limite + " caracteres.");
        return s.trim();
    }
    private static String imagem(String s) {
        String valor = opcional(s, 1000);
        if (valor.isEmpty() || valor.matches("assets/[a-zA-Z0-9_-]+\\.(png|jpg|jpeg|webp|svg)")) return valor;
        try {
            URI uri = URI.create(valor);
            if ("https".equalsIgnoreCase(uri.getScheme()) && uri.getHost() != null && uri.getUserInfo() == null) return valor;
        } catch (IllegalArgumentException ignored) { }
        throw Falha.invalido("Imagem deve ser recurso em assets/ ou URL HTTPS sem credenciais.");
    }
}

