        assertEquals("PEDIDO_FECHADO",assertThrows(Falha.class,() -> api.adicionarItem(p.id(),produto.id(),1)).codigo());
        assertThrows(Falha.class,() -> api.removerItem(p.id(),p.itens().get(0).id()));
        assertThrows(Falha.class,() -> api.atualizarQuantidadeItem(p.id(),p.itens().get(0).id(),2));
        assertThrows(Falha.class,() -> api.cancelarPedido(p.id()));
        assertNotEquals(p.id(),api.abrirPedido(mesa.id()).id());
    }
    // Cenário: cancelar preserva historico.
    @Test void cancelarPreservaHistorico() {
        Pedido p=api.abrirPedido(mesa.id());api.cancelarPedido(p.id());assertEquals(SituacaoMesa.LIVRE,api.consultarMesa(mesa.id()).situacao());
        assertEquals("PEDIDO_CANCELADO",assertThrows(Falha.class,() -> api.cancelarPedido(p.id())).codigo());
    }
    // Cenário: vazio somente pode ser cancelado.
    @Test void vazioSomentePodeSerCancelado() { Pedido p=api.abrirPedido(mesa.id());assertThrows(Falha.class,() -> api.fecharPedido(p.id())); }
    // Cenário: indisponivel nao entra em pedido.
    @Test void indisponivelNaoEntraEmPedido() {
        api.salvarProduto(produto.id(),categoria.id(),produto.nome(),"","",produto.preco(),produto.porcao(),false);
        Pedido p=api.abrirPedido(mesa.id());assertEquals("PRODUTO_INDISPONIVEL",assertThrows(Falha.class,() -> api.adicionarItem(p.id(),produto.id(),1)).codigo());
        assertEquals(1,api.cardapio().produtos().size());assertFalse(api.cardapio().produtos().get(0).disponivel());
    }
    // Cenário: categoria inativa sai do cardapio enao aceita itens.
    @Test void categoriaInativaSaiDoCardapioENaoAceitaItens() {
        api.salvarCategoria(categoria.id(),categoria.nome(),"",false);assertTrue(api.cardapio().produtos().isEmpty());
        Pedido p=api.abrirPedido(mesa.id());assertThrows(Falha.class,() -> api.adicionarItem(p.id(),produto.id(),1));
    }
    // Cenário: exclusao preserva historico.
    @Test void exclusaoPreservaHistorico() {
        Pedido p=api.adicionarItem(api.abrirPedido(mesa.id()).id(),produto.id(),1);api.fecharPedido(p.id());
        assertEquals("REFERENCIADO",assertThrows(Falha.class,() -> api.excluirProduto(produto.id())).codigo());
        assertThrows(Falha.class,() -> api.excluirCategoria(categoria.id()));assertThrows(Falha.class,() -> api.excluirMesa(mesa.id()));
    }
    // Cenário: item de outro pedido nao pode ser alterado.
    @Test void itemDeOutroPedidoNaoPodeSerAlterado() {
        Pedido p=api.adicionarItem(api.abrirPedido(mesa.id()).id(),produto.id(),1);
        Pedido outro=api.abrirPedido(api.salvarMesa(0,3).id());
        assertThrows(Falha.class,() -> api.removerItem(outro.id(),p.itens().get(0).id()));assertEquals(1,api.consultarPedido(p.id()).itens().size());
    }
    // Cenário: rollback unidade de trabalho.
    @Test void rollbackUnidadeDeTrabalho() {
        assertThrows(IllegalStateException.class,() -> repo.transacao(s -> {s.salvarMesa(0,99);throw new IllegalStateException("Simulação");}));
        assertEquals(1,api.listarMesas().size());
    }
    // Cenário: concorrencia nao abre dois pedidos.
    @Test void concorrenciaNaoAbreDoisPedidos() throws Exception {
        ExecutorService pool=Executors.newFixedThreadPool(2);CountDownLatch inicio=new CountDownLatch(1);
        Callable<Boolean> abrir=() -> {inicio.await();try {api.abrirPedido(mesa.id());return true;}catch(Falha e) {return false;}};
        try {var a=pool.submit(abrir);var b=pool.submit(abrir);inicio.countDown();assertNotEquals(a.get(15,TimeUnit.SECONDS),b.get(15,TimeUnit.SECONDS));assertEquals(1,api.listarPedidos().size());}
        finally {pool.shutdownNow();}
    }
    // Cenário: falha de conexao nao expoe detalhes.
    @Test void falhaDeConexaoNaoExpoeDetalhes() {
        org.h2.jdbcx.JdbcDataSource indisponivel=new org.h2.jdbcx.JdbcDataSource();indisponivel.setURL("jdbc:h2:mem:ausente;IFEXISTS=TRUE");
        Falha f=assertThrows(Falha.class,() -> new Restaurante(new JdbcRepositorio(indisponivel)).listarMesas());
        assertEquals("PERSISTENCIA",f.codigo());assertFalse(f.getMessage().contains("jdbc:"));
    }
}

