package br.edu.soa.restaurante;

import br.edu.soa.restaurante.aplicacao.Restaurante;
import br.edu.soa.restaurante.infraestrutura.*;
import jakarta.servlet.*;

public final class Contexto implements ServletContextListener {
    private static volatile Restaurante restaurante;
    private static volatile Credenciais credenciais;
    // Monta credenciais, banco, repositório e casos de uso ao iniciar o WAR.
    @Override public void contextInitialized(ServletContextEvent evento) {
        credenciais = new Credenciais(valor("RESTAURANTE_ADMIN_PASSWORD"),valor("RESTAURANTE_GARCOM_PASSWORD"));
        restaurante = new Restaurante(new JdbcRepositorio(Banco.configurar(valor("DB_URL"),valor("DB_USER"),valor("DB_PASSWORD"))));
    }
    // Remove as referências da aplicação ao encerrar o contexto.
    @Override public void contextDestroyed(ServletContextEvent evento) { restaurante=null; credenciais=null; }
    public static Restaurante restaurante() {
        if (restaurante == null) throw new IllegalStateException("Aplicação ainda não inicializada.");
        return restaurante;
    }
    public static Credenciais credenciais() { return credenciais; }
    private static String valor(String nome) { return System.getProperty("restaurante."+nome,System.getenv(nome)); }
}

// Finalidade: Autenticar as requisições HTTP destinadas aos endpoints SOAP.
package br.edu.soa.restaurante;

import jakarta.servlet.*;
import jakarta.servlet.http.*;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.security.Principal;
import java.util.Base64;

public final class AutenticacaoFilter implements Filter {
    // Autentica a requisição antes de encaminhá-la ao serviço.
    @Override public void doFilter(ServletRequest requisicao,ServletResponse resposta,FilterChain chain) throws IOException,ServletException {
        HttpServletRequest req=(HttpServletRequest)requisicao;
        HttpServletResponse res=(HttpServletResponse)resposta;
        res.setHeader("X-Content-Type-Options","nosniff");
        res.setHeader("Cache-Control","no-store");
        String auth=req.getHeader("Authorization"); String papel=null; String usuario="";
        if(auth!=null && auth.startsWith("Basic ") && auth.length()<4096) {
            try {
                String par=new String(Base64.getDecoder().decode(auth.substring(6)),StandardCharsets.UTF_8);
                int sep=par.indexOf(':');
                if(sep>0) { usuario=par.substring(0,sep); papel=Contexto.credenciais().autenticar(usuario,par.substring(sep+1)); }
            } catch(IllegalArgumentException ignored) { }
        }
        if(papel==null) { res.setHeader("WWW-Authenticate","Basic realm=\"Restaurante\", charset=\"UTF-8\""); res.sendError(401,"Autenticação necessária."); return; }
        final String role=papel; final String user=usuario;
        chain.doFilter(new HttpServletRequestWrapper(req) {
            @Override public Principal getUserPrincipal() { return () -> user; }
            @Override public String getRemoteUser() { return user; }
            @Override public boolean isUserInRole(String r) { return role.equals(r); }
        },res);
    }
}

// Finalidade: Concentrar autorização e tradução das falhas para o contrato SOAP.
package br.edu.soa.restaurante;

import br.edu.soa.restaurante.aplicacao.Falha;
import br.edu.soa.restaurante.soap.*;
import jakarta.xml.ws.WebServiceContext;
import java.util.function.Supplier;

public final class Acesso {
    private Acesso() {}
    // Concentra autorização, execução e tradução segura de falhas.
    public static <T> T executar(WebServiceContext contexto, boolean admin, Supplier<T> acao) throws ErroNegocio_Exception {
        try {
            if (contexto == null || !(contexto.isUserInRole("ADMIN") || (!admin && contexto.isUserInRole("GARCOM")))) {
                throw new Falha("ACESSO_NEGADO", Falha.Tipo.CONFLITO, "Seu perfil não permite esta operação.");
            }
            return acao.get();
        } catch (Falha e) {
            ErroNegocio detalhe = new ErroNegocio(); detalhe.setCodigo(e.codigo()); detalhe.setMensagem(e.getMessage());
            throw new ErroNegocio_Exception(e.getMessage(), detalhe);
        } catch (RuntimeException e) {
            System.getLogger(Acesso.class.getName()).log(System.Logger.Level.ERROR,"Erro interno no adaptador SOAP: {0}",e.getClass().getSimpleName());
            ErroNegocio detalhe = new ErroNegocio(); detalhe.setCodigo("INTERNO"); detalhe.setMensagem("Não foi possível concluir a operação.");
            throw new ErroNegocio_Exception(detalhe.getMensagem(),detalhe);
        }
    }
}

