 }
 public static ItemPedido dto(br.edu.soa.restaurante.dominio.ItemPedido v) { ItemPedido d=new ItemPedido();
  d.setId(v.id());
  d.setProdutoId(v.produtoId());
  d.setNomeProduto(v.nomeProduto());
