// Finalidade: Produzir a imagem PNG do QR com a URL pública do cardápio.
package br.edu.soa.restaurante.infraestrutura;

import java.io.ByteArrayOutputStream;
import java.net.URI;
import com.google.zxing.*;
import com.google.zxing.qrcode.QRCodeWriter;
import com.google.zxing.client.j2se.MatrixToImageWriter;
import br.edu.soa.restaurante.aplicacao.Falha;

public final class QrCode {
    private QrCode() {}
    // Valida a base e a mesa e produz os bytes da imagem PNG.
    public static byte[] gerar(String base,int mesa) {
        if(mesa<1 || mesa>9999) throw Falha.invalido("Número da mesa entre 1 e 9999.");
        if(base==null || base.isBlank()) throw new Falha("CONFIGURACAO",Falha.Tipo.INTERNO,"Configure PUBLIC_BASE_URL com a URL acessível aos clientes.");
        try {
            URI u=URI.create(base);
            if(!java.util.Set.of("http","https").contains(u.getScheme()) || u.getHost()==null || u.getUserInfo()!=null || u.getQuery()!=null || u.getFragment()!=null) throw new IllegalArgumentException();
            String url=base.replaceAll("/+$","")+"/cardapio/index.html?mesa="+mesa;
            var matriz=new QRCodeWriter().encode(url,BarcodeFormat.QR_CODE,320,320);
            ByteArrayOutputStream out=new ByteArrayOutputStream();MatrixToImageWriter.writeToStream(matriz,"PNG",out);return out.toByteArray();
        } catch(Exception e) { throw new Falha("CONFIGURACAO",Falha.Tipo.INTERNO,"Não foi possível gerar o QR Code. Confira PUBLIC_BASE_URL."); }
    }
}

// Finalidade: Atender às consultas públicas do catálogo e à geração de QR no WAR.
package br.edu.soa.restaurante;

import com.fasterxml.jackson.databind.ObjectMapper;
import jakarta.servlet.http.*;
import java.io.IOException;
import java.util.Map;
import br.edu.soa.restaurante.infraestrutura.QrCode;
import br.edu.soa.restaurante.aplicacao.Falha;

/** BFF somente leitura. O navegador não recebe credenciais nem consulta pedidos. */
public final class CardapioServlet extends HttpServlet {
    private final ObjectMapper json=new ObjectMapper();
    // Atende a consulta HTTP e escreve a resposta no formato previsto.
    @Override protected void doGet(HttpServletRequest req,HttpServletResponse res) throws IOException {
        res.setHeader("X-Content-Type-Options","nosniff");
        res.setHeader("Cache-Control","no-store");
        if("/qr".equals(req.getPathInfo())) {
            String mesa=req.getParameter("mesa");
            if(mesa==null || !mesa.matches("[0-9]{1,4}")) { res.sendError(400,"Mesa numérica obrigatória."); return; }
            try {
                byte[] png=QrCode.gerar(System.getProperty("restaurante.PUBLIC_BASE_URL",System.getenv("PUBLIC_BASE_URL")),Integer.parseInt(mesa));
                res.setContentType("image/png");res.getOutputStream().write(png);
            } catch(Falha e) { res.sendError(e.tipo()==Falha.Tipo.VALIDACAO?400:503,e.getMessage()); }
            return;
        }
        if(req.getPathInfo()!=null && !"/cardapio".equals(req.getPathInfo())) { res.sendError(404); return; }
        res.setContentType("application/json;charset=UTF-8");
        try { json.writeValue(res.getOutputStream(),Contexto.restaurante().cardapio()); }
        catch(RuntimeException e) { res.setStatus(503); json.writeValue(res.getOutputStream(),Map.of("codigo","INDISPONIVEL","mensagem","Cardápio temporariamente indisponível.")); }
    }
}

// Finalidade: Construir os clientes SOAP com endereço e credenciais da sessão.
package br.edu.soa.restaurante;

import br.edu.soa.restaurante.soap.*;
import jakarta.xml.ws.*;
import javax.xml.namespace.QName;
import java.net.URI;

/** WSDL local; cada operação recebe um proxy próprio com timeout e autenticação. */
public final class ConexaoSoap {
    private static final String NS="http://restaurante.soa.edu.br/v2";
    private final String usuario,senha;
    public ConexaoSoap(String usuario,String senha) { this.usuario=usuario; this.senha=senha; }
    private <T> T port(String entidade,Class<T> tipo) {
        String base=System.getProperty("soap.base",System.getenv().getOrDefault("SOAP_BASE_URL","http://localhost:8080/restaurante"));
        URI uri=URI.create(base);
        if(!java.util.Set.of("http","https").contains(uri.getScheme()) || uri.getHost()==null) throw new IllegalArgumentException("SOAP_BASE_URL deve ser URL HTTP(S).");
        Service service=Service.create(ConexaoSoap.class.getResource("/wsdl/"+entidade+"Service.wsdl"),new QName(NS,entidade+"Service"));
        T proxy=service.getPort(new QName(NS,entidade+"Port"),tipo);
        var contexto=((BindingProvider)proxy).getRequestContext();
        contexto.put(BindingProvider.ENDPOINT_ADDRESS_PROPERTY,base.replaceAll("/+$","")+"/soap/"+entidade.toLowerCase()+"s");
        contexto.put(BindingProvider.USERNAME_PROPERTY,usuario); contexto.put(BindingProvider.PASSWORD_PROPERTY,senha);
        contexto.put("com.sun.xml.ws.connect.timeout",5000); contexto.put("com.sun.xml.ws.request.timeout",10000);
        return proxy;
    }
    public MesaServicePortType mesas() { return port("Mesa",MesaServicePortType.class); }
    public CategoriaServicePortType categorias() { return port("Categoria",CategoriaServicePortType.class); }
    public ProdutoServicePortType produtos() { return port("Produto",ProdutoServicePortType.class); }
    public PedidoServicePortType pedidos() { return port("Pedido",PedidoServicePortType.class); }
}

// Finalidade: Separar chamadas remotas do trabalho de apresentação na EDT.
package br.edu.soa.restaurante;

import br.edu.soa.restaurante.soap.ErroNegocio_Exception;
import javax.swing.*;
import java.awt.*;
import java.util.concurrent.Callable;
import java.util.concurrent.ExecutionException;
import java.util.function.Consumer;

/** doInBackground faz rede; done roda na EDT. Só uma operação por janela. */
abstract class Janela extends JFrame {
    protected final ConexaoSoap conexao;
    private boolean ocupado;
    private final JLabel mensagem=new JLabel("Pronto");
    protected Janela(String titulo,ConexaoSoap conexao) {
        super(titulo); this.conexao=conexao;
        setDefaultCloseOperation(DISPOSE_ON_CLOSE); setSize(1150,760); setLocationRelativeTo(null);
        add(mensagem,BorderLayout.SOUTH);
    }
    // Executa o trabalho remoto fora da EDT e entrega a atualização à interface.
    protected <T> void remoto(Callable<T> acao,Consumer<T> sucesso) {
        if(ocupado) return;
        ocupado=true; habilitar(getContentPane(),false); mensagem.setText("Comunicando com o servidor…");
        new SwingWorker<T,Void>() {
            @Override protected T doInBackground() throws Exception { return acao.call(); }
            @Override protected void done() {
                ocupado=false; habilitar(getContentPane(),true); mensagem.setText("Pronto");
                try { sucesso.accept(get()); }
                catch(InterruptedException e) { Thread.currentThread().interrupt(); }
                catch(ExecutionException e) { erro(e.getCause()); }
                catch(RuntimeException e) { erro(e); }
                if(!ocupado) atualizarEstado();
            }
        }.execute();
    }
    // Ajusta os controles ao estado recebido do pedido.
    protected void atualizarEstado() {}
    protected void erro(Throwable erro) {
        String texto=erro instanceof ErroNegocio_Exception f ? f.getFaultInfo().getMensagem()
            : erro instanceof IllegalArgumentException ? erro.getMessage()
            : "Não foi possível concluir. Verifique conexão, credenciais, servidor e tente atualizar.";
        JOptionPane.showMessageDialog(this,texto,"Restaurante",JOptionPane.ERROR_MESSAGE);
    }
    private static void habilitar(Container c,boolean v) {
        for(Component x:c.getComponents()) { x.setEnabled(v); if(x instanceof Container filho) habilitar(filho,v); }
    }
    // Obtém as credenciais da interface para criar a conexão autenticada.
    protected static ConexaoSoap login(String usuario) {
        JTextField nome=new JTextField(usuario); JPasswordField senha=new JPasswordField();
        JPanel campos=new JPanel(new GridLayout(0,1,4,4)); campos.add(new JLabel("Usuário")); campos.add(nome); campos.add(new JLabel("Senha")); campos.add(senha);
        if(JOptionPane.showConfirmDialog(null,campos,"Entrar no restaurante",JOptionPane.OK_CANCEL_OPTION)!=JOptionPane.OK_OPTION) return null;
        char[] valor=senha.getPassword();
        try { return new ConexaoSoap(nome.getText().trim(),new String(valor)); }
        finally { java.util.Arrays.fill(valor,'\0'); senha.setText(""); }
    }
}

// Finalidade: Compartilhar o fluxo de cadastro dos painéis Swing.
package br.edu.soa.restaurante;

import javax.swing.*;
import javax.swing.table.DefaultTableModel;
import java.awt.*;
import java.util.List;

/** Lê campos na EDT e envia um snapshot ao SwingWorker. */
abstract class CadastroPanel<T,E> extends JPanel {
    protected final Janela janela;
    protected final ConexaoSoap conexao;
    protected final JPanel formulario=new JPanel(new GridLayout(0,2,6,6));
    protected final DefaultTableModel modelo;
    protected final JTable tabela;
    protected List<T> registros=List.of();
    protected long id;
    protected CadastroPanel(Janela janela,String... colunas) {
        super(new BorderLayout(8,8)); this.janela=janela; conexao=janela.conexao;
        setBorder(BorderFactory.createEmptyBorder(12,12,12,12));
        modelo=new DefaultTableModel(colunas,0) { @Override public boolean isCellEditable(int r,int c) { return false; } };
        tabela=new JTable(modelo); tabela.setSelectionMode(ListSelectionModel.SINGLE_SELECTION);
        add(formulario,BorderLayout.NORTH); add(new JScrollPane(tabela),BorderLayout.CENTER);
        JPanel botoes=new JPanel();
        for(String acao:new String[]{"Novo","Salvar","Excluir","Atualizar"}) {
            JButton b=new JButton(acao); botoes.add(b);
            b.addActionListener(e -> { try {
                switch(acao) {
                    case "Novo" -> { id=0; tabela.clearSelection(); limpar(); }
                    case "Atualizar" -> carregar();
                    case "Salvar" -> { E entrada=ler(); long alvo=id; janela.remoto(() -> { salvar(alvo,entrada); return listar(); },this::exibir); }
                    case "Excluir" -> {
                        if(id==0) throw new IllegalArgumentException("Selecione um registro.");
                        if(JOptionPane.showConfirmDialog(this,"Excluir registro selecionado?","Excluir",JOptionPane.OK_CANCEL_OPTION)==JOptionPane.OK_OPTION) {
                            long alvo=id; janela.remoto(() -> { excluir(alvo); return listar(); },this::exibir);
                        }
                    }
                }
            } catch(RuntimeException x) { janela.erro(x); } });
        }
        add(botoes,BorderLayout.SOUTH);
        tabela.getSelectionModel().addListSelectionListener(e -> {
            int r=tabela.getSelectedRow(); if(!e.getValueIsAdjusting() && r>=0) preencher(registros.get(r));
        });
    }
    protected void campo(String rotulo,JComponent componente) {
        JLabel label=new JLabel(rotulo); label.setLabelFor(componente); formulario.add(label); formulario.add(componente);
    }
    // Obtém os dados necessários e atualiza a apresentação pelo fluxo da janela.
    protected void carregar() { janela.remoto(this::listar,this::exibir); }
    // Apresenta o retorno do servidor na janela.
    protected void exibir(List<T> valores) {
        registros=valores; modelo.setRowCount(0); valores.forEach(v -> modelo.addRow(linha(v))); id=0; limpar();
    }
    protected abstract List<T> listar() throws Exception;
    protected abstract E ler();
    protected abstract void salvar(long id,E entrada) throws Exception;
    protected abstract void excluir(long id) throws Exception;
    protected abstract Object[] linha(T valor);
    protected abstract void preencher(T valor);
    protected abstract void limpar();
}

