  linha.add(new JLabel("Produto"));linha.add(produto);linha.add(new JLabel("Quantidade"));linha.add(quantidade);linha.add(adicionar);linha.add(alterar);linha.add(remover);
  topo.add(mesas);topo.add(linha);add(topo,BorderLayout.NORTH);
  grade.setSelectionMode(ListSelectionModel.SINGLE_SELECTION);gradeItens.setSelectionMode(ListSelectionModel.SINGLE_SELECTION);
  JSplitPane split=new JSplitPane(JSplitPane.VERTICAL_SPLIT,new JScrollPane(grade),new JScrollPane(gradeItens));split.setResizeWeight(.45);
