  atualizar.addActionListener(e -> carregar());
  abrir.addActionListener(e -> { Mesa m=(Mesa)mesa.getSelectedItem();if(m!=null)remoto(() -> conexao.pedidos().abrirPedido(m.getId()),p -> { exibir(p);carregar(); }); });
  grade.getSelectionModel().addListSelectionListener(e -> {int r=grade.getSelectedRow();if(!e.getValueIsAdjusting()&&r>=0) {long id=lista.get(r).getId();remoto(() -> conexao.pedidos().consultarPedido(id),this::exibir);} });
  gradeItens.getSelectionModel().addListSelectionListener(e -> {int r=gradeItens.getSelectedRow();if(r>=0 && selecionado!=null)quantidade.setValue(selecionado.getItens().get(r).getQuantidade());});
  adicionar.addActionListener(e -> { if(selecionado==null)return;Produto p=(Produto)produto.getSelectedItem();if(p==null)return;long id=selecionado.getId();int q=(int)quantidade.getValue();remoto(() -> conexao.pedidos().adicionarItem(id,p.getId(),q),this::aposAlteracao); });
  alterar.addActionListener(e -> {int r=gradeItens.getSelectedRow();if(r<0||selecionado==null)return;long id=selecionado.getId(),item=selecionado.getItens().get(r).getId();int q=(int)quantidade.getValue();remoto(() -> conexao.pedidos().atualizarQuantidadeItem(id,item,q),this::aposAlteracao);});
  remover.addActionListener(e -> {int r=gradeItens.getSelectedRow();if(r<0||selecionado==null)return;long id=selecionado.getId(),item=selecionado.getItens().get(r).getId();remoto(() -> conexao.pedidos().removerItem(id,item),this::aposAlteracao);});
