 }
 private void aposAlteracao(Pedido p) { exibir(p);carregar(); }
 // Solicita a operação remota e apresenta o resultado devolvido pelo servidor.
 private void encerrar(boolean cancelamento) {
  if(selecionado==null)return; long id=selecionado.getId();
  if(JOptionPane.showConfirmDialog(this,cancelamento?"Cancelar este pedido?":"Fechar conta e liberar mesa?","Confirmar",JOptionPane.OK_CANCEL_OPTION)!=JOptionPane.OK_OPTION)return;
  remoto(() -> cancelamento?conexao.pedidos().cancelarPedido(id):conexao.pedidos().fecharPedido(id),p -> { exibir(p);JOptionPane.showMessageDialog(this,"Pedido "+p.getId()+" • "+p.getSituacao()+" | Total R$ "+p.getTotal()+" | Mesa liberada.");carregar(); });
 }
 private record Dados(List<Mesa> mesas,List<Produto> produtos,List<Pedido> pedidos) {}
 // Obtém os dados necessários e atualiza a apresentação pelo fluxo da janela.
 private void carregar() {
  remoto(() -> {
   var ativas=conexao.categorias().listarCategorias().stream().filter(Categoria::isAtivo).map(Categoria::getId).toList();
   return new Dados(conexao.mesas().listarMesas(),conexao.produtos().listarProdutos().stream().filter(p -> p.isDisponivel() && ativas.contains(p.getCategoriaId())).toList(),conexao.pedidos().listarPedidos());
  },d -> {
   long mesaId=mesa.getSelectedItem() instanceof Mesa m?m.getId():0;
   mesa.removeAllItems();d.mesas().forEach(m -> {mesa.addItem(m);if(m.getId()==mesaId)mesa.setSelectedItem(m);});produto.removeAllItems();d.produtos().forEach(produto::addItem);
   lista=d.pedidos();pedidos.setRowCount(0);lista.forEach(p -> pedidos.addRow(new Object[]{p.getId(),p.getMesaId(),p.getSituacao(),p.getTotal()}));
   if(selecionado!=null)lista.stream().filter(p -> p.getId()==selecionado.getId()).findFirst().ifPresent(this::exibir);
  });
 }
 // Apresenta o retorno do servidor na janela.
 private void exibir(Pedido p) { selecionado=p;itens.setRowCount(0);p.getItens().forEach(i -> itens.addRow(new Object[]{i.getId(),i.getNomeProduto(),i.getQuantidade(),i.getPrecoUnitario(),i.getSubtotal()}));conta.setText("Pedido "+p.getId()+" • "+p.getSituacao()+" • Total R$ "+p.getTotal());atualizarEstado(); }
 // Ajusta os controles ao estado recebido do pedido.
 @Override protected void atualizarEstado() {
  boolean aberto=selecionado!=null && selecionado.getSituacao()==SituacaoPedido.ABERTO;
  for(JButton b:new JButton[]{adicionar,alterar,remover,fechar,cancelar})b.setEnabled(aberto);
  abrir.setEnabled(mesa.getSelectedItem() instanceof Mesa m && m.getSituacao()==SituacaoMesa.LIVRE);
 }
 private static DefaultTableModel modelo(String... nomes) { return new DefaultTableModel(nomes,0) { @Override public boolean isCellEditable(int r,int c) {return false;} }; }
 // Inicia a aplicação correspondente a esta classe.
 public static void main(String[] args) {SwingUtilities.invokeLater(() -> {var c=login("garcom");if(c!=null)new TelaPedidos(c).setVisible(true);});}
}

// Finalidade: Criar app.js e ligá-lo ao HTML para consultar o catálogo público.
'use strict';
const el = id => document.getElementById(id);
let dados = { categorias: [], produtos: [] }, categoria = null;
const moeda = new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' });
const numero = new URLSearchParams(location.search).get('mesa');
if (numero && /^[0-9]{1,4}$/.test(numero) && Number(numero) > 0) {
  el('mesa').textContent = `Mesa ${String(Number(numero)).padStart(2, '0')}`;
  el('qr').href = `../api/public/qr?mesa=${Number(numero)}`;
  el('qr').hidden = false;
}
function texto(tag, valor, classe) {
  const n = document.createElement(tag); n.textContent = valor;
  if (classe) n.className = classe;
  return n;
}
function renderizar() {
  const termo = el('busca').value.toLocaleLowerCase('pt-BR').trim();
  const lista = dados.produtos.filter(p => (categoria === null || p.categoriaId === categoria) && `${p.nome} ${p.descricao}`.toLocaleLowerCase('pt-BR').includes(termo));
  el('produtos').replaceChildren();
  for (const p of lista) {
    const card = document.createElement('article'); card.className = 'prato';
    const img = document.createElement('img');
    img.src = typeof p.imagem === 'string' && (/^assets\/[\w-]+\.(png|jpe?g|webp|svg)$/.test(p.imagem) || /^https:\/\//i.test(p.imagem)) ? p.imagem : 'assets/carbonara.svg';
    img.alt = p.nome; img.loading = 'lazy'; img.referrerPolicy = 'no-referrer';
    img.addEventListener('error', () => { img.src = 'assets/carbonara.svg'; }, { once: true });
    const detalhes = texto('div', '', 'detalhes');
    if (!p.disponivel) detalhes.append(texto('span', 'Indisponível no momento', 'indisponivel'));
    detalhes.append(texto('h3', p.nome), texto('p', p.descricao), texto('p', p.porcao, 'porcao'), texto('p', moeda.format(p.preco), 'preco'));
    card.append(img, detalhes); el('produtos').append(card);
  }
  el('status').textContent = lista.length ? `${lista.length} ${lista.length === 1 ? 'opção' : 'opções'} para você.` : 'Nenhum prato encontrado. Experimente outra busca ou categoria.';
}
function filtros() {
  el('categorias').replaceChildren();
  for (const c of [{ id: null, nome: 'Todo o cardápio' }, ...dados.categorias]) {
    const b = texto('button', c.nome); b.type = 'button'; b.setAttribute('aria-pressed', String(c.id === categoria));
    b.addEventListener('click', () => { categoria = c.id; filtros(); renderizar(); [...el('categorias').children].find(x => x.textContent === c.nome)?.focus(); });
    el('categorias').append(b);
  }
}
async function carregar() {
  el('tentar').hidden = true; el('status').textContent = 'Buscando os sabores de hoje…';
  const controle = new AbortController(); const tempo = setTimeout(() => controle.abort(), 10000);
  try {
    const resposta = await fetch('../api/public/cardapio', { signal: controle.signal, headers: { Accept: 'application/json' }, credentials: 'omit' });
    if (!resposta.ok) throw new Error('Cardápio indisponível');
    dados = await resposta.json();
    if (!Array.isArray(dados.categorias) || !Array.isArray(dados.produtos)) throw new Error('Resposta inválida');
    categoria = null; filtros(); renderizar();
  } catch {
    el('status').textContent = 'Não conseguimos carregar o cardápio. Verifique sua conexão e tente novamente.';
    el('tentar').hidden = false;
  } finally { clearTimeout(tempo); }
}
el('busca').addEventListener('input', renderizar);
el('tentar').addEventListener('click', carregar);
carregar();

