/** DTOs de saída: o contrato HTTP não depende de anotações no domínio. */
public final class Saidas {
    private Saidas() {}
    public record MesaDto(long id,int numero,SituacaoMesa situacao) {}
    public record CategoriaDto(long id,String nome,String descricao,boolean ativo) {}
    public record ProdutoDto(long id,long categoriaId,String nome,String descricao,String imagem,BigDecimal preco,String porcao,boolean disponivel) {}
    public record ItemDto(long id,long produtoId,String nomeProduto,int quantidade,BigDecimal precoUnitario,BigDecimal subtotal) {}
    @io.swagger.v3.oas.annotations.media.Schema(example="{\"id\":1,\"mesaId\":1,\"dataHora\":\"2026-10-31T15:00:00Z\",\"situacao\":\"ABERTO\",\"itens\":[{\"id\":1,\"produtoId\":1,\"nomeProduto\":\"Carbonara\",\"quantidade\":2,\"precoUnitario\":55.00,\"subtotal\":110.00}],\"total\":110.00}")
    public record PedidoDto(long id,long mesaId,String dataHora,SituacaoPedido situacao,List<ItemDto> itens,BigDecimal total) {}
