// Finalidade: Definir autenticação HTTP e autorização das rotas por papel.
package br.edu.soa.restaurante.rest;

import br.edu.soa.restaurante.infraestrutura.Credenciais;
import tools.jackson.databind.ObjectMapper;
import org.springframework.context.annotation.*;
import org.springframework.http.HttpMethod;
import org.springframework.security.authentication.*;
import org.springframework.security.config.annotation.web.builders.HttpSecurity;
import org.springframework.security.config.http.SessionCreationPolicy;
import org.springframework.security.core.authority.SimpleGrantedAuthority;
import org.springframework.security.web.SecurityFilterChain;
import java.util.*;

@Configuration
public class Seguranca {
    @Bean AuthenticationProvider autenticacao(Credenciais credenciais) {
        return new AuthenticationProvider() {
            public org.springframework.security.core.Authentication authenticate(org.springframework.security.core.Authentication a) {
                String papel=credenciais.autenticar(a.getName(),String.valueOf(a.getCredentials()));
                if(papel==null) throw new BadCredentialsException("Credenciais inválidas.");
                return UsernamePasswordAuthenticationToken.authenticated(a.getName(),null,List.of(new SimpleGrantedAuthority("ROLE_"+papel)));
            }
            public boolean supports(Class<?> tipo) { return UsernamePasswordAuthenticationToken.class.isAssignableFrom(tipo); }
        };
    }
    @Bean SecurityFilterChain cadeia(HttpSecurity http,AuthenticationProvider provider,ObjectMapper json) throws Exception {
        return http.authenticationProvider(provider).csrf(c -> c.disable())
            .sessionManagement(s -> s.sessionCreationPolicy(SessionCreationPolicy.STATELESS))
            .authorizeHttpRequests(a -> a
                .requestMatchers("/cardapio/**","/api/public/**").permitAll()
                .requestMatchers("/swagger-ui/**","/swagger-ui.html","/v3/api-docs/**").hasRole("ADMIN")
                .requestMatchers(HttpMethod.GET,"/api/mesas/**","/api/categorias/**","/api/produtos/**").hasAnyRole("ADMIN","GARCOM")
                .requestMatchers("/api/pedidos/**").hasAnyRole("ADMIN","GARCOM")
                .requestMatchers("/api/**").hasRole("ADMIN").anyRequest().denyAll())
            .httpBasic(b -> b.authenticationEntryPoint((req,res,e) -> {
                res.setStatus(401); res.setHeader("WWW-Authenticate","Basic realm=\"Restaurante\", charset=\"UTF-8\"");
                res.setContentType("application/json"); json.writeValue(res.getOutputStream(),new Erros.Erro("NAO_AUTENTICADO","Informe suas credenciais."));
            }))
            .exceptionHandling(e -> e.accessDeniedHandler((req,res,x) -> {
                res.setStatus(403); res.setContentType("application/json");
                json.writeValue(res.getOutputStream(),new Erros.Erro("ACESSO_NEGADO","Seu perfil não permite esta operação."));
            })).build();
    }
}

